// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *InsCoverageLedgerEntry) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := tables.CompanyTable(company, InsCoverageLedgerEntryTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (entry_no)`,
		fmt.Sprintf("%s$Ins_Coverage_Ledger_Entry$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (insurance_no, posting_date)`,
		fmt.Sprintf("%s$Ins_Coverage_Ledger_Entry$insurance_date", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index insurance_date: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (insurance_no, disposed_fa, posting_date)`,
		fmt.Sprintf("%s$Ins_Coverage_Ledger_Entry$insurance_disposed_date", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index insurance_disposed_date: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (fa_no, insurance_no, disposed_fa, posting_date)`,
		fmt.Sprintf("%s$Ins_Coverage_Ledger_Entry$fa_insurance", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index fa_insurance: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (fa_no, disposed_fa, posting_date)`,
		fmt.Sprintf("%s$Ins_Coverage_Ledger_Entry$fa_disposed_date", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index fa_disposed_date: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (document_no, posting_date)`,
		fmt.Sprintf("%s$Ins_Coverage_Ledger_Entry$document", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index document: %w", err)
	}
	var keys []sift.Key
	for _, spec := range insCoverageLedgerEntrySIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, InsCoverageLedgerEntryTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, InsCoverageLedgerEntryTableName, keys)
}

// insCoverageLedgerEntrySIFTSpecs are the table's keys with sum_index_fields
func insCoverageLedgerEntrySIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{
		{
			Name:   "insurance_date",
			Fields: []sift.Column{{Name: "insurance_no", Kind: sift.KindText}, {Name: "posting_date", Kind: sift.KindDate}},
			Sums:   []sift.Column{{Name: "amount", Kind: sift.KindDecimal}},
		},
		{
			Name:   "insurance_disposed_date",
			Fields: []sift.Column{{Name: "insurance_no", Kind: sift.KindText}, {Name: "disposed_fa", Kind: sift.KindBool}, {Name: "posting_date", Kind: sift.KindDate}},
			Sums:   []sift.Column{{Name: "amount", Kind: sift.KindDecimal}},
		},
		{
			Name:   "fa_insurance",
			Fields: []sift.Column{{Name: "fa_no", Kind: sift.KindText}, {Name: "insurance_no", Kind: sift.KindText}, {Name: "disposed_fa", Kind: sift.KindBool}, {Name: "posting_date", Kind: sift.KindDate}},
			Sums:   []sift.Column{{Name: "amount", Kind: sift.KindDecimal}},
		},
	}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *InsCoverageLedgerEntry) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := tables.CompanyTable(t.company, InsCoverageLedgerEntryTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range insCoverageLedgerEntrySIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, InsCoverageLedgerEntryTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: InsCoverageLedgerEntryTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, InsCoverageLedgerEntryTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

